package com.example.iptvplayer

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.unit.dp
import androidx.compose.ui.viewinterop.AndroidView
import androidx.media3.common.MediaItem
import androidx.media3.exoplayer.ExoPlayer
import androidx.media3.ui.PlayerView
import java.net.URL

data class Channel(val name: String, val url: String)

fun parseM3u(text: String): List<Channel> {
    val list = mutableListOf<Channel>()
        var name: String? = null
            for (raw in text.lines()) {
                    val line = raw.trim()
                            if (line.startsWith("#EXTINF")) {
                                        name = line.substringAfterLast(",").trim()
                                                } else if (line.isNotEmpty() && !line.startsWith("#")) {
                                                            list.add(Channel(if (name.isNullOrBlank()) line else name, line))
                                                                        name = null
                                                                                }
                                                                                    }
                                                                                        return list
                                                                                        }

                                                                                        class MainActivity : ComponentActivity() {
                                                                                            override fun onCreate(savedInstanceState: Bundle?) {
                                                                                                    super.onCreate(savedInstanceState)
                                                                                                            setContent {
                                                                                                                        MaterialTheme { IptvApp() }
                                                                                                                                }
                                                                                                                                    }
                                                                                                                                    }

                                                                                                                                    @Composable
                                                                                                                                    fun IptvApp() {
                                                                                                                                        val context = LocalContext.current
                                                                                                                                            val player = remember { ExoPlayer.Builder(context).build() }
                                                                                                                                                DisposableEffect(Unit) { onDispose { player.release() } }

                                                                                                                                                    var link by remember { mutableStateOf("") }
                                                                                                                                                        var channels by remember { mutableStateOf(listOf<Channel>()) }
                                                                                                                                                            var selected by remember { mutableStateOf<Channel?>(null) }
                                                                                                                                                                var status by remember { mutableStateOf("") }

                                                                                                                                                                    LaunchedEffect(selected) {
                                                                                                                                                                            selected?.let {
                                                                                                                                                                                        player.setMediaItem(MediaItem.fromUri(it.url))
                                                                                                                                                                                                    player.prepare()
                                                                                                                                                                                                                player.playWhenReady = true
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                Column(Modifier.fillMaxSize().statusBarsPadding().padding(8.dp)) {
                                                                                                                                                                                                                                        if (selected != null) {
                                                                                                                                                                                                                                                    AndroidView(
                                                                                                                                                                                                                                                                    factory = { PlayerView(it).apply { this.player = player } },
                                                                                                                                                                                                                                                                                    modifier = Modifier.fillMaxWidth().height(220.dp)
                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                            Text(selected!!.name, Modifier.padding(vertical = 8.dp))
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                            OutlinedTextField(
                                                                                                                                                                                                                                                                                                                                        value = link,
                                                                                                                                                                                                                                                                                                                                                    onValueChange = { link = it },
                                                                                                                                                                                                                                                                                                                                                                label = { Text("M3U link yahan daalo") },
                                                                                                                                                                                                                                                                                                                                                                            modifier = Modifier.fillMaxWidth()
                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                            Button(
                                                                                                                                                                                                                                                                                                                                                                                                        onClick = {
                                                                                                                                                                                                                                                                                                                                                                                                                        status = "Load ho raha hai..."
                                                                                                                                                                                                                                                                                                                                                                                                                                        Thread {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val text = URL(link.trim()).readText()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val result = parseM3u(text)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    channels = result
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            status = "${result.size} channels mile"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch (e: Exception) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        status = "Error: ${e.message}"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }.start()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    modifier = Modifier.padding(vertical = 8.dp)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) { Text("Load karo") }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Text(status)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            LazyColumn {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        items(channels) { ch ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ch.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Modifier
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .fillMaxWidth()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .clickable { selected = ch }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .padding(12.dp)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        HorizontalDivider()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } 